  text-decoration: none;
  justify-self: start;
}

.mast__aside {
  margin: 0;
  font-size: 0.72rem;
  letter-spacing: 0.16em;
  text-transform: uppercase;
  font-weight: 400;
  opacity: 0.8;
}

.mast__ask {
  justify-self: end;
  font-size: 0.82rem;
  text-decoration: none;
  border-bottom: 1px solid oklch(0.98 0 0 / 0.45);
  padding-bottom: 0.12rem;
}

.mast__ask:hover {
  border-bottom-color: oklch(0.98 0 0);
}

.hero {
  min-height: 100svh;
  display: grid;
