.mast__ask {
  justify-self: end;
  font-size: 0.82rem;
  text-decoration: none;
  border-bottom: 1px solid oklch(0.98 0 0 / 0.45);
  padding-bottom: 0.12rem;
}

.mast__ask:hover {
