:root {
  --bg: oklch(0.08 0 0);
  --surface: oklch(0.13 0.018 250);
  --ink: oklch(0.96 0.012 250);
  --muted: oklch(0.74 0.028 250);
  --primary: oklch(0.48 0.14 250);
  --primary-glow: oklch(0.62 0.13 250);
  --accent: oklch(0.78 0.13 85);
  --accent-soft: oklch(0.88 0.08 88);
  --wine: oklch(0.28 0.08 18);
  --valley: oklch(0.62 0.11 175);
