  text-decoration: none;
  justify-self: start;
}

.mast__aside {
  margin: 0;
  font-size: 0.72rem;
  letter-spacing: 0.16em;
  text-transform: uppercase;
  font-weight: 400;
  opacity: 0.8;
}

.mast__ask {
  justify-self: end;
  font-size: 0.82rem;
  text-decoration: none;
  border-bottom: 1px solid oklch(0.98 0 0 / 0.45);
  padding-bottom: 0.12rem;
}

.mast__ask:hover {
  border-bottom-color: oklch(0.98 0 0);
}

.hero {
  min-height: 100svh;
  display: grid;
  place-items: center;
  padding: 7rem 1.5rem 4rem;
  padding-left: calc(var(--plumb) + 1.5rem);
  text-align: center;
}

.hero__moon {
  margin: 0 0 1.75rem;
  width: min(46vmin, 320px);
  aspect-ratio: 1;
  border-radius: 50%;
  overflow: hidden;
  box-shadow: 0 0 0 1px oklch(0.78 0.13 85 / 0.55);
}

.hero__moon img {
  width: 100%;
  height: 100%;
  max-width: none;
  object-fit: cover;
  object-position: 14% 40%;
  animation: moon-breathe 14s var(--ease-out) infinite alternate;
}

@keyframes moon-breathe {
  from {
    transform: scale(1);
  }
  to {
    transform: scale(1.06);
  }
}

.hero h1 {
  font-size: clamp(2.4rem, 7vw, 6rem);
  letter-spacing: -0.03em;
  line-height: 0.95;
}

.hero__lede {
  max-width: min(46ch, 100%);
  margin: 1.4rem auto 0;
  color: var(--muted);
  font-size: 1.02rem;
  font-weight: 300;
  line-height: 1.7;
}

.hero__down {
  margin-top: 2.8rem;
  display: inline-flex;
  flex-direction: column;
  align-items: center;
  gap: 0.55rem;
  text-decoration: none;
  font-size: 0.72rem;
  letter-spacing: 0.18em;
  text-transform: uppercase;
  color: var(--accent-soft);
}

.hero__down svg {
  width: 0.7rem;
  height: 1.6rem;
  stroke: var(--accent);
  fill: none;
  stroke-width: 1.4;
}

.table {
  padding: 4rem 1.5rem 6rem;
  padding-left: calc(var(--plumb) + 1.5rem);
  background:
    radial-gradient(ellipse 70% 60% at 50% 40%, oklch(0.28 0.08 18 / 0.55), transparent 70%),
    var(--bg);
}

.table__intro {
  max-width: 42ch;
  margin: 0 auto 3.5rem;
  text-align: center;
  color: var(--muted);
  font-weight: 300;
}

.table__stage {
  position: relative;
  max-width: 1100px;
  margin: 0 auto;
  min-height: min(78vh, 720px);
  display: grid;
  grid-template-columns: 1fr 1.15fr 0.9fr;
  grid-template-rows: auto auto auto;
  gap: 1.25rem 1.5rem;
  align-items: center;
  justify-items: center;
}

.obj {
  position: relative;
  padding: 0;
  border: 0;
  background: none;
  cursor: pointer;
  border-radius: 50%;
  overflow: hidden;
  box-shadow: 0 0 0 1px oklch(0.78 0.13 85 / 0.35);
  isolation: isolate;
}

.obj img {
  width: 100%;
  height: 100%;
  max-width: none;
  object-fit: cover;
  transition: transform 0.7s var(--ease-out);
}

.obj span {
  position: absolute;
  left: 50%;
  bottom: 0.7rem;
  transform: translateX(-50%);
  font-size: 0.68rem;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: oklch(0.98 0.01 90);
  text-shadow: 0 1px 8px oklch(0.1 0 0 / 0.8);
  white-space: nowrap;
}

.obj:hover img,
.obj[aria-expanded="true"] img {
  transform: scale(1.08);
}

.obj:hover,
.obj[aria-expanded="true"] {
  box-shadow: 0 0 0 1px var(--accent);
}

.obj--bust {
  grid-column: 2;
  grid-row: 1 / 3;
  width: min(42vw, 340px);
  aspect-ratio: 1;
}

.obj--bust img {
  object-position: 8% 38%;
}

.obj--fruit {
  grid-column: 1;
  grid-row: 2;
  width: min(28vw, 210px);
  aspect-ratio: 1;
  justify-self: end;
}

.obj--fruit img {
  object-position: 48% 62%;
}

.obj--wine {
  grid-column: 3;
  grid-row: 1;
  width: min(24vw, 180px);
  aspect-ratio: 1;
  justify-self: start;
}

.obj--wine img {
  object-position: 78% 48%;
}

.obj--gold {
  grid-column: 3;
  grid-row: 2;
  width: min(18vw, 140px);
  aspect-ratio: 1;
  justify-self: center;
}

.obj--gold img {
  object-position: 92% 55%;
}

.table__note {
  grid-column: 1 / -1;
  grid-row: 3;
  min-height: 6.5rem;
  max-width: 46ch;
  text-align: center;
  color: var(--muted);
  font-weight: 300;
  font-size: 0.98rem;
}

.table__note p {
  margin: 0;
  display: none;
}

.table__note p.is-on,
.table__note p:first-child {
  display: block;
}

.table__note:has(p.is-on) p:first-child:not(.is-on) {
  display: none;
}

.descent {
  height: 420vh;
  position: relative;
}

.descent__pin {
  position: sticky;
  top: 0;
  height: 100svh;
  overflow: hidden;
  background: var(--bg);
}

.world {
  position: absolute;
  inset: 0;
  display: grid;
  place-items: center;
}

.world__frame {
  overflow: hidden;
  will-change: transform, opacity;
}

.world__frame img {
  width: 100%;
  height: 100%;
  max-width: none;
  object-fit: cover;
}

.world--temple .world__frame {
  width: 100%;
  height: 100%;
}

.world--temple img {
  transform: scale(1.08);
}

.world--valley .world__frame {
  width: min(96vw, 1280px);
  height: min(82vh, 760px);
  clip-path: url(#vista);
}

.world--archive .world__frame {
  width: min(78vw, 920px);
  height: min(88vh, 860px);
  clip-path: url(#arch);
}

.world--cameo .world__frame {
  width: min(68vmin, 560px);
  height: min(68vmin, 560px);
  border-radius: 50%;
  box-shadow: 0 0 0 1px oklch(0.78 0.13 85 / 0.45);
}

.world--cameo img {
  object-position: 16% 42%;
}

.world__veil {
  position: absolute;
  inset: 0;
  pointer-events: none;
  background:
    radial-gradient(ellipse at center, transparent 40%, oklch(0.08 0 0 / 0.55) 100%),
    linear-gradient(to top, oklch(0.08 0 0 / 0.55), transparent 35%);
}

.world__caption {
  position: absolute;
  left: calc(var(--plumb) + 1.5rem);
  right: 1.5rem;
  bottom: 2.2rem;
  z-index: 4;
  max-width: 36rem;
}

.world__place {
  margin: 0 0 0.35rem;
  font-size: 0.7rem;
  letter-spacing: 0.2em;
  text-transform: uppercase;
  color: var(--accent);
}

.world__line {
  margin: 0;
  font-family: var(--display);
  font-size: clamp(1.35rem, 3vw, 2.15rem);
  letter-spacing: -0.02em;
  line-height: 1.2;
}

.carte {
  padding: 6rem 1.5rem 7rem;
  padding-left: calc(var(--plumb) + 1.5rem);
  background: var(--bg);
}

.carte__head {
  max-width: 40rem;
  margin-bottom: 4rem;
}

.carte__mark {
  margin: 0 0 0.8rem;
  font-size: 0.72rem;
  letter-spacing: 0.18em;
  text-transform: uppercase;
  color: var(--accent);
}

.carte__head h2 {
  font-size: clamp(2rem, 4.5vw, 3.6rem);
  margin-bottom: 1rem;
}

.carte__head p {
  margin: 0;
  color: var(--muted);
  max-width: 48ch;
  font-weight: 300;
}

.carte__list {
  list-style: none;
  margin: 0;
  padding: 0;
  display: flex;
  flex-direction: column;
  gap: 0;
}

.course {
  display: grid;
  grid-template-columns: minmax(7rem, 0.28fr) minmax(0, 1fr) minmax(8rem, 0.42fr);
  gap: 1.25rem 2rem;
  align-items: start;
  padding: 2.4rem 0;
  border-top: 1px solid oklch(0.96 0.01 250 / 0.12);
}

.course:last-child {
  border-bottom: 1px solid oklch(0.96 0.01 250 / 0.12);
}

.course__meta {
  display: flex;
  flex-direction: column;
  gap: 0.35rem;
  font-size: 0.72rem;
  letter-spacing: 0.16em;
  text-transform: uppercase;
  color: var(--muted);
  padding-top: 0.45rem;
}

.course__meta span:first-child {
  color: var(--accent);
}

.course h3 {
  font-size: clamp(1.6rem, 3vw, 2.4rem);
  margin-bottom: 0.7rem;
}

.course p {
  margin: 0;
  max-width: 52ch;
  color: var(--muted);
  font-weight: 300;
}

.course__cut {
  margin: 0;
  justify-self: end;
  width: min(100%, 220px);
}

.course__cut img {
  width: 100%;
  height: 100%;
  max-width: none;
  object-fit: cover;
}

.course__cut--round {
  aspect-ratio: 1;
  border-radius: 50%;
  overflow: hidden;
}

.course__cut--round img {
  object-position: 50% 58%;
  transform: scale(1.35);
}

.course__cut--arch {
  height: 210px;
  clip-path: url(#arch);
}

.course__cut--arch img {
  object-position: 50% 40%;
  height: 210px;
}

.course__cut--river {
  height: 240px;
  clip-path: url(#river);
}

.course__cut--river img {
  height: 240px;
  object-position: 50% 60%;
}

.course__cut--shard {
  height: 200px;
  clip-path: url(#shard);
}

.course__cut--shard img {
  height: 200px;
  object-position: 50% 55%;
}

.night {
  position: relative;
  min-height: 100svh;
  padding: 6rem 1.5rem 5rem;
  padding-left: calc(var(--plumb) + 1.5rem);
  overflow: hidden;
  background: oklch(0.07 0.02 250);
}

.night__stars {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  pointer-events: none;
}

.night__temple {
  position: absolute;
  right: -8%;
  bottom: -12%;
  width: min(72vw, 820px);
  clip-path: url(#shard);
  opacity: 0.55;
  pointer-events: none;
  mask-image: linear-gradient(to top left, oklch(0 0 0 / 0.95), transparent 78%);
}

.night__temple img {
  width: 100%;
  height: auto;
  filter: saturate(1.1) contrast(1.05);
}

.night__copy {
  position: relative;
  z-index: 2;
  max-width: 36rem;
}

.night__copy h2 {
  font-size: clamp(2.2rem, 5vw, 4.2rem);
  margin-bottom: 1rem;
}

.night__copy p {
  margin: 0;
  color: var(--muted);
  font-weight: 300;
  max-width: 46ch;
}

.ledger {
  position: relative;
  z-index: 2;
  margin-top: 3rem;
  max-width: 34rem;
}

.ledger__row {
  display: grid;
  grid-template-columns: 9.5rem 1fr;
  gap: 1rem;
  align-items: baseline;
  padding: 0.85rem 0;
  border-bottom: 1px solid oklch(0.96 0.01 250 / 0.16);
}

.ledger__row span {
  font-size: 0.72rem;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: var(--accent-soft);
}

.ledger__row input,
.ledger__row select,
.ledger__row textarea {
  width: 100%;
  background: transparent;
  border: 0;
  padding: 0.2rem 0;
  outline: none;
  color: var(--ink);
  border-radius: 0;
}

.ledger__row input::placeholder,
.ledger__row textarea::placeholder {
  color: oklch(0.62 0.03 250);
}

.ledger__row select {
  appearance: none;
  background-image: linear-gradient(45deg, transparent 50%, var(--accent) 50%),
    linear-gradient(135deg, var(--accent) 50%, transparent 50%);
  background-position:
    calc(100% - 12px) 50%,
    calc(100% - 6px) 50%;
  background-size: 6px 6px;
  background-repeat: no-repeat;
}

.ledger__row--note {
  align-items: start;
}

.ledger__row textarea {
  resize: vertical;
  min-height: 4.5rem;
  line-height: 1.7;
}

.ledger__act {
  display: flex;
  justify-content: flex-start;
  padding-top: 2rem;
}

.seal-btn {
  display: inline-flex;
  align-items: center;
  gap: 1rem;
  background: none;
  border: 0;
  padding: 0;
  cursor: pointer;
}

.seal-btn__wax {
  width: 4.25rem;
  height: 4.25rem;
  border-radius: 50%;
  display: grid;
  place-items: center;
  background: radial-gradient(circle at 35% 30%, oklch(0.86 0.12 85), oklch(0.62 0.14 72));
  color: var(--on-accent);
  font-family: var(--display);
  font-size: 1.7rem;
  box-shadow: inset 0 -8px 16px oklch(0.4 0.1 70 / 0.45);
  transition: transform 0.35s var(--ease-out);
}

.seal-btn:hover .seal-btn__wax,
.seal-btn:focus-visible .seal-btn__wax {
  transform: scale(0.94);
}

.seal-btn:active .seal-btn__wax {
  transform: scale(0.88);
}

.seal-btn__label {
  font-size: 0.78rem;
  letter-spacing: 0.16em;
  text-transform: uppercase;
}

.ledger__reply {
  margin: 1.5rem 0 0;
  color: var(--accent-soft);
  font-family: var(--display);
  font-size: 1.25rem;
  line-height: 1.35;
}

.colophon {
  padding: 3.5rem 1.5rem 3rem;
  padding-left: calc(var(--plumb) + 1.5rem);
  border-top: 1px solid oklch(0.96 0.01 250 / 0.1);
}

.colophon__mark {
  font-family: var(--display);
  font-size: 1.5rem;
  margin: 0 0 0.6rem;
}

.colophon p {
  margin: 0;
  max-width: 48ch;
  color: var(--muted);
  font-weight: 300;
  font-size: 0.92rem;
}

.colophon__coords {
  margin-top: 1.1rem !important;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  font-size: 0.68rem !important;
  color: var(--accent) !important;
}

@media (max-width: 860px) {
  :root {
    --plumb: 0.9rem;
  }

  .mast {
    grid-template-columns: 1fr auto;
  }

  .mast__aside {
    display: none;
  }

  .table__stage {
    grid-template-columns: 1fr 1fr;
    min-height: 0;
  }

  .obj--bust {
    grid-column: 1 / -1;
    grid-row: 1;
    width: min(64vw, 280px);
  }

  .obj--fruit {
    grid-column: 1;
    grid-row: 2;
    width: min(42vw, 170px);
    justify-self: center;
  }

  .obj--wine {
    grid-column: 2;
    grid-row: 2;
    width: min(38vw, 150px);
    justify-self: center;
  }

  .obj--gold {
    grid-column: 1 / -1;
    grid-row: 3;
    width: min(32vw, 120px);
  }

  .table__note {
    grid-row: 4;
  }

  .course {
    grid-template-columns: 1fr;
    gap: 0.8rem;
  }

  .course__cut {
    justify-self: start;
    width: min(100%, 260px);
  }

  .ledger__row {
    grid-template-columns: 1fr;
    gap: 0.35rem;
  }

  .night__temple {
    width: 110vw;
    right: -20%;
    opacity: 0.35;
  }
}

@media (max-width: 560px) {
  .hero {
    padding-top: 6.5rem;
  }

  .hero__moon {
    width: min(48vmin, 200px);
  }

  .world__caption {
    bottom: 1.4rem;
  }
}

@media (pointer: coarse) {
  .cursor {
    display: none !important;
  }
}

@media (prefers-reduced-motion: reduce) {
  .iris {
    display: none;
  }

  .hero__moon img,
  .obj img,
  .seal-btn__wax {
    animation: none;
    transition: none;
  }

  html {
    scroll-behavior: auto;
  }
}

