  pointer-events: none;
  mix-blend-mode: difference;
}

.cursor span {
  display: block;
  width: 100%;
  height: 100%;
  border: 1px solid oklch(0.98 0 0);
  border-radius: 50%;
  transform: scale(1);
  transition: transform 0.35s var(--ease-out);
}

.cursor.is-hot span {
  transform: scale(2.1);
}

.mast {
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
