  font-size: 1.02rem;
  font-weight: 300;
  line-height: 1.7;
}

.hero__down {
  margin-top: 2.8rem;
  display: inline-flex;
  flex-direction: column;
  align-items: center;
  gap: 0.55rem;
  text-decoration: none;
  font-size: 0.72rem;
  letter-spacing: 0.18em;
  text-transform: uppercase;
  color: var(--accent-soft);
}

.hero__down svg {
