  gap: 1rem;
  align-items: baseline;
  padding: 0.85rem 0;
  border-bottom: 1px solid oklch(0.96 0.01 250 / 0.16);
}

.ledger__row span {
  font-size: 0.72rem;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: var(--accent-soft);
}

.ledger__row input,
.ledger__row select,
.ledger__row textarea {
  width: 100%;
  background: transparent;
  border: 0;
  padding: 0.2rem 0;
  outline: none;
  color: var(--ink);
  border-radius: 0;
}

.ledger__row input::placeholder,
.ledger__row textarea::placeholder {
  color: oklch(0.62 0.03 250);
}

.ledger__row select {
  appearance: none;
  background-image: linear-gradient(45deg, transparent 50%, var(--accent) 50%),
    linear-gradient(135deg, var(--accent) 50%, transparent 50%);
  background-position:
    calc(100% - 12px) 50%,
    calc(100% - 6px) 50%;
  background-size: 6px 6px;
  background-repeat: no-repeat;
}

.ledger__row--note {
  align-items: start;
}

.ledger__row textarea {
  resize: vertical;
  min-height: 4.5rem;
  line-height: 1.7;
}

.ledger__act {
  display: flex;
  justify-content: flex-start;
  padding-top: 2rem;
}

.seal-btn {
  display: inline-flex;
  align-items: center;
  gap: 1rem;
  background: none;
  border: 0;
  padding: 0;
  cursor: pointer;
}

.seal-btn__wax {
  width: 4.25rem;
  height: 4.25rem;
  border-radius: 50%;
  display: grid;
  place-items: center;
  background: radial-gradient(circle at 35% 30%, oklch(0.86 0.12 85), oklch(0.62 0.14 72));
  color: var(--on-accent);
  font-family: var(--display);
  font-size: 1.7rem;
  box-shadow: inset 0 -8px 16px oklch(0.4 0.1 70 / 0.45);
  transition: transform 0.35s var(--ease-out);
}

.seal-btn:hover .seal-btn__wax,
.seal-btn:focus-visible .seal-btn__wax {
  transform: scale(0.94);
}

.seal-btn:active .seal-btn__wax {
  transform: scale(0.88);
}

.seal-btn__label {
  font-size: 0.78rem;
  letter-spacing: 0.16em;
  text-transform: uppercase;
}

.ledger__reply {
  margin: 1.5rem 0 0;
  color: var(--accent-soft);
  font-family: var(--display);
  font-size: 1.25rem;
  line-height: 1.35;
}

.colophon {
  padding: 3.5rem 1.5rem 3rem;
  padding-left: calc(var(--plumb) + 1.5rem);
  border-top: 1px solid oklch(0.96 0.01 250 / 0.1);
}

.colophon__mark {
  font-family: var(--display);
  font-size: 1.5rem;
  margin: 0 0 0.6rem;
}

.colophon p {
  margin: 0;
  max-width: 48ch;
  color: var(--muted);
  font-weight: 300;
  font-size: 0.92rem;
}

.colophon__coords {
  margin-top: 1.1rem !important;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  font-size: 0.68rem !important;
  color: var(--accent) !important;
}

@media (max-width: 860px) {
  :root {
    --plumb: 0.9rem;
  }

  .mast {
    grid-template-columns: 1fr auto;
  }

  .mast__aside {
    display: none;
  }

  .table__stage {
    grid-template-columns: 1fr 1fr;
    min-height: 0;
  }

  .obj--bust {
    grid-column: 1 / -1;
    grid-row: 1;
    width: min(64vw, 280px);
  }

  .obj--fruit {
    grid-column: 1;
    grid-row: 2;
    width: min(42vw, 170px);
    justify-self: center;
  }

  .obj--wine {
    grid-column: 2;
    grid-row: 2;
    width: min(38vw, 150px);
    justify-self: center;
  }

  .obj--gold {
    grid-column: 1 / -1;
    grid-row: 3;
    width: min(32vw, 120px);
  }

  .table__note {
    grid-row: 4;
  }

  .course {
    grid-template-columns: 1fr;
    gap: 0.8rem;
  }

  .course__cut {
    justify-self: start;
    width: min(100%, 260px);
  }

  .ledger__row {
    grid-template-columns: 1fr;
    gap: 0.35rem;
  }

  .night__temple {
    width: 110vw;
    right: -20%;
    opacity: 0.35;
  }
}

@media (max-width: 560px) {
  .hero {
    padding-top: 6.5rem;
  }

  .hero__moon {
    width: min(58vmin, 240px);
    height: min(58vmin, 240px);
  }

  .world__caption {
    bottom: 1.4rem;
  }
}

@media (pointer: fine) {
  body.has-cursor,
  body.has-cursor a,
  body.has-cursor button {
    cursor: none;
  }
}

@media (prefers-reduced-motion: reduce) {
  .iris {
    display: none;
  }

  .hero__moon img,
  .obj img,
  .seal-btn__wax {
    animation: none;
    transition: none;
  }

  html {
    scroll-behavior: auto;
  }
}

