import puppeteer from 'puppeteer-core';
import { mkdir } from 'fs/promises';

const out = '/tmp/elysian-shots';
await mkdir(out, { recursive: true });

const browser = await puppeteer.launch({
  executablePath: '/Applications/Google Chrome.app/Contents/MacOS/Google Chrome',
  headless: true,
  args: ['--hide-scrollbars', '--disable-gpu'],
});

async function shoot(name, { width, height, selector = null, scrollFrac = null }) {
  const page = await browser.newPage();
  await page.setViewport({ width, height, deviceScaleFactor: 1 });
  await page.goto('http://127.0.0.1:4173', { waitUntil: 'networkidle0', timeout: 30000 });
  await page.evaluate(() => document.fonts.ready);
  await page.evaluate(() => Promise.all([...document.images].map(img => img.decode().catch(() => {}))));
  await new Promise(r => setTimeout(r, 1800));
  if (selector) {
    await page.$eval(selector, el => el.scrollIntoView({ block: 'start' }));
    await new Promise(r => setTimeout(r, 500));
  }
  if (scrollFrac != null) {
    const box = await page.$eval('#descent', el => {
      const r = el.getBoundingClientRect();
      return { top: r.top + window.scrollY, height: el.offsetHeight };
    });
    await page.evaluate((y) => window.scrollTo(0, y), box.top + box.height * scrollFrac);
    await new Promise(r => setTimeout(r, 700));
  }
  await page.screenshot({ path: `${out}/${name}.png` });
  await page.close();
  console.log('wrote', name);
}

