.world__caption {
  position: absolute;
  left: calc(var(--plumb) + 1.5rem);
  right: 1.5rem;
  bottom: 2.2rem;
  z-index: 4;
  max-width: 36rem;
}

.world__place {
  margin: 0 0 0.35rem;
  font-size: 0.7rem;
  letter-spacing: 0.2em;
  text-transform: uppercase;
  color: var(--accent);
}

.world__line {
  margin: 0;
  font-family: var(--display);
  font-size: clamp(1.35rem, 3vw, 2.15rem);
  letter-spacing: -0.02em;
  line-height: 1.2;
}

.carte {
  padding: 6rem 1.5rem 7rem;
  padding-left: calc(var(--plumb) + 1.5rem);
  background: var(--bg);
}

.carte__head {
  max-width: 40rem;
  margin-bottom: 4rem;
}

.carte__mark {
  margin: 0 0 0.8rem;
  font-size: 0.72rem;
  letter-spacing: 0.18em;
  text-transform: uppercase;
  color: var(--accent);
}

.carte__head h2 {
  font-size: clamp(2rem, 4.5vw, 3.6rem);
  margin-bottom: 1rem;
}

.carte__head p {
