  color: var(--muted);
  max-width: 48ch;
  font-weight: 300;
}

.carte__list {
  list-style: none;
  margin: 0;
  padding: 0;
  display: flex;
  flex-direction: column;
  gap: 0;
}

.course {
  display: grid;
  grid-template-columns: minmax(7rem, 0.28fr) minmax(0, 1fr) minmax(8rem, 0.42fr);
  gap: 1.25rem 2rem;
  align-items: start;
  padding: 2.4rem 0;
  border-top: 1px solid oklch(0.96 0.01 250 / 0.12);
}

.course:last-child {
  border-bottom: 1px solid oklch(0.96 0.01 250 / 0.12);
}

.course__meta {
  display: flex;
  flex-direction: column;
  gap: 0.35rem;
  font-size: 0.72rem;
  letter-spacing: 0.16em;
  text-transform: uppercase;
  color: var(--muted);
  padding-top: 0.45rem;
}

.course__meta span:first-child {
  color: var(--accent);
}

.course h3 {
  font-size: clamp(1.6rem, 3vw, 2.4rem);
  margin-bottom: 0.7rem;
}

.course p {
  margin: 0;
  max-width: 52ch;
  color: var(--muted);
  font-weight: 300;
}

.course__cut {
  position: relative;
  margin: 0;
  justify-self: end;
  width: min(100%, 220px);
  overflow: hidden;
}

.course__cut img {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  max-width: none;
  object-fit: cover;
}

.course__cut--round {
  aspect-ratio: 1;
  height: min(100%, 220px);
  width: min(100%, 220px);
  border-radius: 50%;
  overflow: hidden;
}

.course__cut--round img {
  object-position: 78% 52%;
}

.course__cut--arch {
  height: 210px;
  clip-path: url(#arch);
}

.course__cut--arch img {
  object-position: 50% 40%;
}

.course__cut--river {
  height: 240px;
  clip-path: url(#river);
}

.course__cut--river img {
  object-position: 50% 60%;
}

.course__cut--shard {
  height: 200px;
  clip-path: url(#shard);
}

.course__cut--shard img {
  object-position: 50% 55%;
}

.night {
  position: relative;
  min-height: 100svh;
  padding: 6rem 1.5rem 5rem;
  padding-left: calc(var(--plumb) + 1.5rem);
  overflow: hidden;
  background: oklch(0.07 0.02 250);
}

.night__stars {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  pointer-events: none;
}

.night__temple {
  position: absolute;
  right: -8%;
  bottom: -12%;
  width: min(72vw, 820px);
  clip-path: url(#shard);
  opacity: 0.55;
  pointer-events: none;
  mask-image: linear-gradient(to top left, oklch(0 0 0 / 0.95), transparent 78%);
