import puppeteer from 'puppeteer-core';

const out = '/tmp/elysian-shots';
const browser = await puppeteer.launch({
  executablePath: '/Applications/Google Chrome.app/Contents/MacOS/Google Chrome',
  headless: true,
  args: ['--hide-scrollbars', '--disable-gpu'],
});

async function pageAt(width, height) {
  const page = await browser.newPage();
  await page.setViewport({ width, height, deviceScaleFactor: 1 });
  const errors = [];
  page.on('pageerror', e => errors.push(String(e)));
  page.on('console', msg => { if (msg.type() === 'error') errors.push(msg.text()); });
  await page.goto('http://127.0.0.1:4173', { waitUntil: 'networkidle0', timeout: 30000 });
  await page.evaluate(() => document.fonts.ready);
  await page.evaluate(() => Promise.all([...document.images].map(img => img.decode().catch(() => {}))));
  await new Promise(r => setTimeout(r, 1600));
  return { page, errors };
}

{
  const { page, errors } = await pageAt(1440, 900);
  console.log('console errors', errors);
  await page.$eval('#table', el => el.scrollIntoView({ block: 'start' }));
  await new Promise(r => setTimeout(r, 400));
